<?php
namespace App\Policies;
use App\Models\{ProjectBudget,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class ProjectBudgetPolicy { use HandlesAuthorization,CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_project::budget');} public function view(User $u,ProjectBudget $r):bool{return $this->canForRecord($u,'view_project::budget',$r);} public function create(User $u):bool{return $u->can('create_project::budget');} public function update(User $u,ProjectBudget $r):bool{return $r->status==='draft'&&$this->canForRecord($u,'update_project::budget',$r);} public function delete(User $u,ProjectBudget $r):bool{return $r->status==='draft'&&!$r->categories()->exists()&&$this->canForRecord($u,'delete_project::budget',$r);} public function deleteAny(User $u):bool{return false;} public function forceDelete(User $u,ProjectBudget $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function restore(User $u,ProjectBudget $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function replicate(User $u,ProjectBudget $r):bool{return false;} public function reorder(User $u):bool{return false;} public function submit(User $u,ProjectBudget $r):bool{return $this->canForRecord($u,'submit_project_budget',$r);} public function approve(User $u,ProjectBudget $r):bool{return $this->canForRecord($u,'approve_project_budget',$r);} public function reject(User $u,ProjectBudget $r):bool{return $this->canForRecord($u,'reject_project_budget',$r);} public function revision(User $u,ProjectBudget $r):bool{return $this->canForRecord($u,'create_budget_revision',$r);} public function cancel(User $u,ProjectBudget $r):bool{return $this->canForRecord($u,'cancel_project_budget',$r);} }
